package com.xlays.nexus.modules.player;
import com.xlays.nexus.modules.Module;
import net.minecraft.client.Minecraft;import net.minecraft.core.BlockPos;import net.minecraft.core.Direction;import net.minecraft.world.InteractionHand;import net.minecraft.world.item.BlockItem;import net.minecraft.world.phys.BlockHitResult;import net.minecraft.world.phys.Vec3;import java.lang.reflect.Field;
public final class Scaffold extends Module {
 private int delay=2,ticks; private boolean placeUnder=true;
 public Scaffold(){super("Scaffold",Category.PLAYER,false);numberSetting("delay","Place delay",()->delay,v->delay=v.intValue(),1,10,1);booleanSetting("under","Place below player",()->placeUnder,v->placeUnder=v);}
 @Override public void onTick(){var mc=Minecraft.getInstance();var p=mc.player;if(p==null||mc.level==null||mc.gameMode==null||mc.screen!=null||!mc.options.keyUse.isDown())return;if(++ticks<delay)return;ticks=0;BlockPos target=p.blockPosition().below();if(!placeUnder||!mc.level.isEmptyBlock(target))return;BlockPos support=target.below();if(mc.level.isEmptyBlock(support)||!mc.level.getBlockState(support).isSolid())return;int old=getSelected(p),slot=-1;for(int i=0;i<9;i++)if(p.getInventory().getItem(i).getItem() instanceof BlockItem){slot=i;break;}if(slot<0)return;setSelected(p,slot);mc.gameMode.useItemOn(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(support),Direction.UP,support,false));setSelected(p,old);}
 private int getSelected(net.minecraft.client.player.LocalPlayer p){try{Field f=p.getInventory().getClass().getDeclaredField("selected");f.setAccessible(true);return f.getInt(p.getInventory());}catch(ReflectiveOperationException|RuntimeException ignored){return 0;}}
 private void setSelected(net.minecraft.client.player.LocalPlayer p,int slot){try{Field f=p.getInventory().getClass().getDeclaredField("selected");f.setAccessible(true);f.setInt(p.getInventory(),slot);}catch(ReflectiveOperationException|RuntimeException ignored){}}
}